public sealed class MarkdownFormat : IPublishFormatPlugin
{
    public string Name => "Пример: Markdown (один файл)";

    public string FileExtension => "md";   // без точки: окно сохранения предложит *.md

    public void Publish(DitaProject project, string mapPath, PublishOptions options, string outputPath)
    {
        // 1. Дерево карты без строк, исключённых условиями сборки.
        var tree = MapTree.Build(project, mapPath, node => PublishFilter.IsIncluded(node, options));
        var sb = new StringBuilder("# " + tree.Root.Title + "\n\n");

        // 2. Топики и разделы без своего топика (topichead) в порядке карты.
        foreach (var item in tree.PublicationOrderWithHeadings)
        {
            var level = Math.Clamp(item.Level + 1, 2, 6);
            if (item.IsHeadingOnly)
            {
                sb.Append(new string('#', level)).Append(' ').Append(item.Title).Append("\n\n");
                continue;
            }

            // 3. Документ топика с подставленными conref.
            var document = RefResolver.ExpandConrefs(project, project.GetDocument(item.TargetPath!));
            // ... перевод элементов в Markdown; элементы с исключёнными условиями пропускаются:
            //     PublishFilter.IsIncluded(element, options); текст ключей — project.TextWithKeys(element, item.KeyScopeChain)
        }

        // 4. Запись через временный файл: при сбое прежний результат не портится.
        AtomicFile.WriteAllText(outputPath, sb.ToString(), new UTF8Encoding(false));
    }
}
